const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

const clone = value => JSON.parse(JSON.stringify(value));
const snapshot = repo => ({ documents: clone(repo.documents), audit: clone(repo.audit) });
const assertUnchanged = (repo, before, label) =>
  assert.deepEqual(snapshot(repo), before, `${label}: state must be unchanged`);

const setup = () => {
  const repo = new DocumentRepository([
    { id: 'a-active', tenant: 'a', owner: 'e1', deleted: false, archived: false },
    { id: 'a-other', tenant: 'a', owner: 'e2', deleted: false, archived: false },
    { id: 'a-archived', tenant: 'a', owner: 'e2', deleted: false, archived: true },
    { id: 'a-deleted', tenant: 'a', owner: 'e1', deleted: true, archived: false },
    { id: 'b-active', tenant: 'b', owner: 'e1', deleted: false, archived: false },
  ]);
  return { repo, service: new DocumentService(repo) };
};

const adminA = { tenant: 'a', user: 'admin', role: 'admin' };
const editorA = { tenant: 'a', user: 'e1', role: 'editor' };
const viewerA = { tenant: 'a', user: 'e1', role: 'viewer' };
const adminB = { tenant: 'b', user: 'admin', role: 'admin' };

const expectError = (repo, fn, message, label) => {
  const before = snapshot(repo);
  assert.throws(fn, err => err instanceof Error && err.message === message, label);
  assertUnchanged(repo, before, label);
};

// --- success: admin may archive any visible document in their tenant ---
{
  const { repo, service } = setup();
  service.archive(adminA, 'a-other');
  assert.equal(repo.documents.find(d => d.id === 'a-other').archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'admin', document: 'a-other' }]);
}

// --- success: editor may archive a document they own ---
{
  const { repo, service } = setup();
  service.archive(editorA, 'a-active');
  assert.equal(repo.documents.find(d => d.id === 'a-active').archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'e1', document: 'a-active' }]);
}

// --- repeating archive is a no-op (permission enforced first) ---
{
  const { repo, service } = setup();
  service.archive(adminA, 'a-archived');
  assert.deepEqual(repo.audit, [], 'already archived: admin no-op must not audit');
  service.archive(adminA, 'a-active');
  service.archive(adminA, 'a-active');
  assert.deepEqual(repo.audit, [{ actor: 'admin', document: 'a-active' }]);
  service.archive(editorA, 'a-active'); // editor owns it, already archived
  assert.deepEqual(repo.audit, [{ actor: 'admin', document: 'a-active' }], 'editor no-op must not audit');
}

// --- editor forbidden for visible documents they do not own ---
{
  const { repo, service } = setup();
  expectError(repo, () => service.archive(editorA, 'a-other'), 'forbidden', 'editor non-owner');
  expectError(repo, () => service.archive(editorA, 'a-archived'), 'forbidden', 'editor non-owner archived');
}

// --- viewer never may archive, even own/archived documents ---
{
  const { repo, service } = setup();
  expectError(repo, () => service.archive(viewerA, 'a-active'), 'forbidden', 'viewer own active');
  expectError(repo, () => service.archive(viewerA, 'a-other'), 'forbidden', 'viewer other active');
  expectError(repo, () => service.archive(viewerA, 'a-archived'), 'forbidden', 'viewer archived');
}

// --- missing, deleted and foreign-tenant all throw 'not found', even for admin ---
{
  const { repo, service } = setup();
  expectError(repo, () => service.archive(adminA, 'missing'), 'not found', 'missing as admin');
  expectError(repo, () => service.archive(editorA, 'missing'), 'not found', 'missing as editor');
  expectError(repo, () => service.archive(viewerA, 'missing'), 'not found', 'missing as viewer');
  expectError(repo, () => service.archive(adminA, 'a-deleted'), 'not found', 'deleted as admin');
  expectError(repo, () => service.archive(editorA, 'a-deleted'), 'not found', 'deleted as editor');
  expectError(repo, () => service.archive(viewerA, 'a-deleted'), 'not found', 'deleted as viewer');
  expectError(repo, () => service.archive(adminA, 'b-active'), 'not found', 'foreign as admin');
  expectError(repo, () => service.archive(editorA, 'b-active'), 'not found', 'foreign as editor');
  expectError(repo, () => service.archive(viewerA, 'b-active'), 'not found', 'foreign as viewer');
  expectError(repo, () => service.archive(adminB, 'a-active'), 'not found', 'foreign tenant actor');
}

// --- failures leave prior successes untouched, audit append-only in order ---
{
  const { repo, service } = setup();
  service.archive(adminA, 'a-other');
  service.archive(editorA, 'a-active');
  const before = snapshot(repo);
  expectError(repo, () => service.archive(editorA, 'a-other'), 'forbidden', 'mixed: editor non-owner');
  expectError(repo, () => service.archive(adminA, 'a-deleted'), 'not found', 'mixed: deleted');
  assertUnchanged(repo, before, 'mixed state');
  assert.deepEqual(repo.audit, [
    { actor: 'admin', document: 'a-other' },
    { actor: 'e1', document: 'a-active' },
  ]);
  assert.equal(repo.documents.find(d => d.id === 'a-other').archived, true);
  assert.equal(repo.documents.find(d => d.id === 'a-active').archived, true);
}

console.log('authorization checks passed');

